import { OwnerType } from '../models/permission.model';

/**
 * Shared utility for permission string normalization and transformation.
 * Consolidates logic used across AuthDataService, PermissionService, and QAToolsService.
 */
export class PermissionUtils {
  private static readonly SINGULAR_MAP: Record<string, string> = {
    vendors: 'vendor',
    clients: 'client',
    distributors: 'distributor',
    users: 'user',
    userroles: 'userrole',
    roles: 'role',
    themes: 'theme',
    mapsets: 'mapset',
    assets: 'asset',
    devices: 'device',
    simcards: 'simcard',
    fuelcards: 'fuelcard',
    zones: 'zone',
    alerts: 'alert',
    iotypes: 'iotype',
    deviceconfigprofiles: 'deviceconfigprofile',
    assetratingprofiles: 'assetratingprofile',
    assetstateprofiles: 'assetstateprofile',
    overspeedprofiles: 'overspeedprofile',
    roadprofiles: 'roadprofile',
    geolockprofiles: 'geolockprofile',
    customfields: 'customfield',
    costcentres: 'costcentre',
    assetgroups: 'assetgroup',
    assetcategories: 'assetcategory',
    zonegroups: 'zonegroup',
    smsgatewayproviders: 'smsgatewayprovider',
    smsgateways: 'smsgateway',
  };

  /**
   * Reverse of SINGULAR_MAP: singular → plural (e.g., 'alert' → 'alerts').
   * Used to check tier-scoped wildcard grants like `client:alerts`.
   */
  private static readonly PLURAL_MAP: Record<string, string> =
    Object.fromEntries(
      Object.entries(PermissionUtils.SINGULAR_MAP).map(([plural, singular]) => [
        singular,
        plural,
      ]),
    );

  /**
   * Gets the plural/legacyRights key for a singular resource name.
   * Falls back to appending 's' if no mapping exists.
   * e.g., 'alert' → 'alerts', 'device' → 'devices'
   */
  static getPluralForm(singular: string): string {
    return this.PLURAL_MAP[singular.toLowerCase()] ?? `${singular}s`;
  }

  /**
   * Gets the singular form of a plural resource/metric name.
   * Preserves hyphens (e.g. 'companion-cameras' → 'companion-camera').
   */
  static getSingularForm(plural: string): string {
    const lower = plural.toLowerCase();
    if (lower in this.SINGULAR_MAP) {
      return this.SINGULAR_MAP[lower];
    }
    if (lower.endsWith('s') && !lower.endsWith('ss')) {
      return lower.slice(0, -1);
    }
    return lower;
  }

  /**
   * Normalizes resource names from backend format to internal format.
   * - Converts to lowercase
   * - Removes hyphens
   * - Converts plural to singular
   */
  static normalizeResourceName(resource: string): string {
    const normalized = resource.toLowerCase().replaceAll('-', '');
    return this.SINGULAR_MAP[normalized] ?? normalized;
  }

  /**
   * Normalizes a permission string (e.g., 'Vendors:Create' -> 'vendor:create')
   */
  static normalizePermission(permission: string): string {
    const separator = permission.includes(':') ? ':' : '.';
    const [resource, action] = permission.split(separator);

    if (!action) {
      return this.normalizeResourceName(resource);
    }

    const normalizedResource = this.normalizeResourceName(resource);
    return `${normalizedResource}:${action}`;
  }

  /**
   * Parses a permission string to extract tier prefix and resource:action.
   */
  static parsePermission(permission: string): {
    tierPrefix: OwnerType | undefined;
    resourceAction: string;
  } {
    const tiers: OwnerType[] = ['system', 'distributor', 'vendor', 'client'];
    const parts = permission.split(':');

    if (parts.length >= 2 && tiers.includes(parts[0] as OwnerType)) {
      const tierPrefix = parts[0] as OwnerType;
      const resourceAction = parts.slice(1).join(':');
      return { tierPrefix, resourceAction };
    }

    return { tierPrefix: undefined, resourceAction: permission };
  }

  /**
   * Transforms prefixed format (e.g., 'list-users') to internal format ('user:list')
   */
  static transformToInternalFormat(resourceAction: string): string | null {
    // Pattern 1: 'list-{resource}s' -> '{resource}:list'
    const listPluralPattern = /^list-(.+)s$/;
    const listPluralMatch = listPluralPattern.exec(resourceAction);
    if (listPluralMatch) {
      const resource = listPluralMatch[1].replaceAll('-', '');
      const singularResource = this.normalizeResourceName(resource + 's');
      return `${singularResource}:list`;
    }

    // Pattern 2: 'list-{resource}' -> '{resource}:list'
    if (resourceAction.startsWith('list-')) {
      const resource = resourceAction.substring(5).replaceAll('-', '');
      return `${this.normalizeResourceName(resource)}:list`;
    }

    // Pattern 3: already singular resource:action or simple action
    if (resourceAction.includes(':')) {
      return this.normalizePermission(resourceAction);
    }

    return null;
  }

  /**
   * Returns a set of all potential internal permission strings for a given UI permission.
   * bridges the gap between 'client:list-users' and 'user:list'.
   */
  static getInternalMappings(permission: string): string[] {
    const { tierPrefix, resourceAction } = this.parsePermission(permission);
    const results = [permission];

    // Normalize input permission format
    results.push(this.normalizePermission(permission));

    // Try to extract internal resource:action (e.g. 'list-users' -> 'user:list')
    const internal = this.transformToInternalFormat(resourceAction);
    if (internal !== null) {
      results.push(internal);
      if (tierPrefix) {
        results.push(`${tierPrefix}:${internal}`);
      }
    }

    // Also include normalized resourceAction if it contains a colon
    if (resourceAction.includes(':')) {
      results.push(this.normalizePermission(resourceAction));
    }

    return [...new Set(results)];
  }
}
