import { EMPTY, Observable, expand, map, reduce } from 'rxjs';

/**
 * Drain every page of a paginated list endpoint into a single array.
 *
 * Offsets step by `pageSize`, never by the number of items returned: the API
 * derives its page number from `offset / limit`, so a short page would
 * otherwise misalign every subsequent request and skip records. Stops on an
 * empty page as well as on `count`, because some endpoints over-report `count`.
 */
export function fetchAllPages<T>(
  pageSize: number,
  query: (
    offset: number,
    limit: number,
  ) => Observable<{ items?: T[]; count?: number }>,
): Observable<T[]> {
  const fetchPage = (offset: number) =>
    query(offset, pageSize).pipe(
      map((response) => ({
        items: response.items ?? [],
        nextOffset: offset + pageSize,
        count: response.count ?? 0,
      })),
    );

  return fetchPage(0).pipe(
    expand((page) =>
      page.items.length > 0 && page.nextOffset < page.count
        ? fetchPage(page.nextOffset)
        : EMPTY,
    ),
    reduce((all: T[], page) => all.concat(page.items), [] as T[]),
  );
}
