import { inject, Injectable } from '@angular/core';
import { AuthDataService } from './auth-data.service';
import {
  PermissionExpression,
  PermissionQuery,
  OwnerType,
} from '../models/permission.model';
import { isDefined, isNullOrUndefined } from '../../shared/utils';
import { PermissionUtils } from '../utils/permission.utils';

@Injectable({
  providedIn: 'root',
})
export class PermissionService {
  private readonly authData = inject(AuthDataService);

  /**
   * Checks if the user has the required permissions based on fine-grained roles
   * and hierarchical constraints.
   * @param expression The permission expression to evaluate.
   * @param contextLayer Optional context level ('client', 'vendor', etc.) to isolate relative permissions.
   * @returns true if access is granted, false otherwise.
   */
  canAccess(
    expression: PermissionExpression | undefined,
    contextLayer?: OwnerType,
  ): boolean {
    if (
      isNullOrUndefined(expression) ||
      expression === '' ||
      (Array.isArray(expression) && expression.length === 0)
    ) {
      return true;
    }

    const userOwnerType = this.authData.getUserOwnerType() as OwnerType;
    const result = this.evaluateExpression(
      expression,
      userOwnerType,
      contextLayer,
    );

    return result;
  }

  private evaluateExpression(
    expression: PermissionExpression,
    userOwnerType: OwnerType,
    contextLayer?: OwnerType,
  ): boolean {
    if (typeof expression === 'string') {
      return this.checkSinglePermission(
        expression,
        userOwnerType,
        contextLayer,
      );
    }

    if (Array.isArray(expression)) {
      return expression.every((e) =>
        this.evaluateExpression(e, userOwnerType, contextLayer),
      );
    }

    return this.evaluateQuery(expression, userOwnerType, contextLayer);
  }

  private evaluateQuery(
    query: PermissionQuery,
    userOwnerType: OwnerType,
    contextLayer?: OwnerType,
  ): boolean {
    if (query.and) {
      return query.and.every((e) =>
        this.evaluateExpression(e, userOwnerType, contextLayer),
      );
    }

    if (query.or) {
      return query.or.some((e) =>
        this.evaluateExpression(e, userOwnerType, contextLayer),
      );
    }

    if (isDefined(query.not)) {
      return !this.evaluateExpression(query.not, userOwnerType, contextLayer);
    }

    return true;
  }

  private checkSinglePermission(
    permission: string,
    userOwnerType: OwnerType,
    contextLayer?: OwnerType,
  ): boolean {
    // System users bypass all permission checks
    if (userOwnerType === 'system') {
      return true;
    }

    const { tierPrefix, resourceAction } = this.parsePermission(permission);

    // If context layer is provided, validate against it
    if (isDefined(contextLayer)) {
      // Prefixed permissions: must match context layer
      if (isDefined(tierPrefix)) {
        if (tierPrefix !== contextLayer) {
          return false;
        }
      } else {
        // Unprefixed permissions in isolated context: must match user's tier
        // If checking in a 'client' context but user is 'vendor', deny
        if (contextLayer !== userOwnerType) {
          return false;
        }
      }
    }

    return this.checkPermissionWithTierAwareness(
      permission,
      tierPrefix,
      resourceAction,
      userOwnerType,
    );
  }

  /**
   * Parses a permission string to extract tier prefix and resource:action.
   * Examples:
   *   'distributor:users:create' -> { tierPrefix: 'distributor', resourceAction: 'users:create' }
   *   'vendor:list' -> { tierPrefix: 'vendor', resourceAction: 'list' }
   *   'users:create' -> { tierPrefix: undefined, resourceAction: 'users:create' }
   */
  private parsePermission(permission: string): {
    tierPrefix: OwnerType | undefined;
    resourceAction: string;
  } {
    return PermissionUtils.parsePermission(permission);
  }

  /**
   * Checks permission using tier-aware prefix matching.
   * For a distributor user checking 'distributor:users:create':
   *   - First try exact match with prefix: 'distributor:users:create'
   *   - Then try unprefixed match: 'users:create' (since it's their tier)
   * For a distributor user checking 'vendor:create':
   *   - Only exact match: 'vendor:create' (lower tier, must be prefixed)
   */
  private checkPermissionWithTierAwareness(
    originalPermission: string,
    tierPrefix: OwnerType | undefined,
    resourceAction: string,
    userOwnerType: OwnerType,
  ): boolean {
    // If no tier prefix in the permission, check it directly as unprefixed
    if (isNullOrUndefined(tierPrefix)) {
      return this.authData.hasPermission(resourceAction);
    }

    // If permission has a tier prefix, first try exact match (with prefix)
    const prefixedPermission = `${tierPrefix}:${resourceAction}`;
    if (this.authData.hasPermission(prefixedPermission)) {
      return true;
    }

    // If the tier prefix matches the user's tier, also check unprefixed version
    // (e.g., distributor user has 'user:list' unprefixed for distributor-level access)
    if (tierPrefix === userOwnerType) {
      // Transform the permission format from tier:action-resource to resource:action
      const transformedPermission =
        PermissionUtils.transformToInternalFormat(resourceAction);
      if (isDefined(transformedPermission)) {
        return this.authData.hasPermission(transformedPermission);
      }
      // Also try the original resourceAction as-is
      return this.authData.hasPermission(resourceAction);
    }

    return false;
  }
}
