/**
 * Odometer / distance calculation source.
 *
 * Chooses what the ingestion pipeline measures trip distance from. Configured per account
 * tier and inherited downwards - distributor, then vendor, then client - with a tier left
 * unset meaning "inherit from parent".
 *
 * Keep the values in step with:
 * - cypherview.telematics.api .../Domain/Accounts/OdometerSourceType.cs
 * - cypherview.message.grabber/src/modules/trip_detection/odometer_source.py
 */
export const ODOMETER_SOURCES = [
  'gpsOnly',
  'canWithGpsFallback',
  'canOnly',
] as const;

export type OdometerSource = (typeof ODOMETER_SOURCES)[number];

/**
 * What applies when no tier in the hierarchy sets a value. This is the pipeline's
 * long-standing behaviour, so an account that configures nothing is unaffected.
 */
export const DEFAULT_ODOMETER_SOURCE: OdometerSource = 'canWithGpsFallback';

/** Translation key for a source value's human-readable label. */
export function odometerSourceLabelKey(source: string): string {
  return `ADMIN.ODOMETER_SOURCE.VALUES.${source}`;
}
