/**
 * Default relative width for columns that do not declare a {@link widthWeight}.
 * Used when distributing table width across the currently visible column set.
 */
export const TREE_TABLE_DEFAULT_COLUMN_WEIGHT = 1.5;

/**
 * Pixels of minimum width granted per unit of {@link widthWeight} when a column
 * declares no explicit `minWidth`. The sum across visible columns becomes the
 * table's `min-width`, below which the table scrolls horizontally instead of
 * truncating every cell.
 */
export const TREE_TABLE_MIN_PX_PER_WEIGHT = 70;

export interface TreeTableColumnWidthInput {
  field: string | number | symbol;
  width?: string;
  widthWeight?: number;
  minWidth?: number;
}

export interface TreeTableColumnWidths<T> {
  /**
   * Visible columns with their computed share and their resolved px floor. The
   * floor doubles as the drag limit when columns are resizable, so a user can
   * never drag a column narrower than the point its content stops being legible.
   */
  columns: (T & { width: string; minWidth: number })[];
  /** Sum of every visible column's px floor. Bound to the table's `min-width`. */
  tableMinWidth: number;
}

function minWidthFor(col: TreeTableColumnWidthInput): number {
  return (
    col.minWidth ??
    (col.widthWeight ?? TREE_TABLE_DEFAULT_COLUMN_WEIGHT) *
      TREE_TABLE_MIN_PX_PER_WEIGHT
  );
}

/**
 * Distributes column widths as percentages that always sum to 100% for the
 * given visible column set, and reports the px floor below which the table
 * should scroll horizontally rather than shrink further.
 *
 * Columns with a higher {@link widthWeight} receive a larger share; Name and
 * other primary columns should use the largest weights.
 *
 * Explicit `width` values on input columns are replaced by the computed share.
 *
 * This function is intentionally pure - it must not read services or stored
 * preferences. Callers layer any user overrides on top of its result.
 */
export function allocateTreeTableColumnWidths<
  T extends TreeTableColumnWidthInput,
>(columns: T[]): TreeTableColumnWidths<T> {
  if (columns.length === 0) {
    return { columns: [], tableMinWidth: 0 };
  }

  const tableMinWidth = columns.reduce(
    (sum, col) => sum + minWidthFor(col),
    0,
  );

  if (columns.length === 1) {
    return {
      columns: [
        { ...columns[0], width: '100%', minWidth: minWidthFor(columns[0]) },
      ],
      tableMinWidth,
    };
  }

  const weights = columns.map(
    (col) => col.widthWeight ?? TREE_TABLE_DEFAULT_COLUMN_WEIGHT,
  );
  const totalWeight = weights.reduce((sum, weight) => sum + weight, 0);

  const tenths = weights.map((weight) =>
    Math.floor((weight / totalWeight) * 1000),
  );
  const remainder = 1000 - tenths.reduce((sum, value) => sum + value, 0);

  const maxWeightIndex = weights.indexOf(Math.max(...weights));
  tenths[maxWeightIndex] += remainder;

  return {
    columns: columns.map((col, index) => ({
      ...col,
      width: `${tenths[index] / 10}%`,
      minWidth: minWidthFor(col),
    })),
    tableMinWidth,
  };
}
