import { Injectable, signal } from '@angular/core';
import type { ClientResponse } from '../../api';

/**
 * Shared service for managing preview client state.
 * Decouples AuthDataService from ClientDataService to avoid circular dependency.
 */
@Injectable({
  providedIn: 'root',
})
export class PreviewStateService {
  private readonly previewClient = signal<Partial<ClientResponse> | null>(null);

  /**
   * Get the preview client signal.
   */
  readonly preview = this.previewClient.asReadonly();

  /**
   * Set the preview client.
   */
  setPreviewClient(client: Partial<ClientResponse> | null): void {
    this.previewClient.set(client);
  }

  /**
   * Clear the preview client.
   */
  clearPreviewClient(): void {
    this.previewClient.set(null);
  }

  /**
   * Get the current preview client value.
   */
  getPreviewClient(): Partial<ClientResponse> | null {
    return this.previewClient();
  }
}
