import { inject } from '@angular/core';
import { CanActivateFn, Router, ActivatedRouteSnapshot } from '@angular/router';
import { PermissionService } from '../services/permission.service';
import { isNullOrUndefined } from '../../shared/utils';
import { OwnerType, PermissionExpression } from '../models/permission.model';

export const permissionGuard: CanActivateFn = (
  route: ActivatedRouteSnapshot,
) => {
  const permissionService = inject(PermissionService);
  const router = inject(Router);
  const expectedPermissions = route.data['expectedPermissions'] as
    | PermissionExpression
    | undefined;
  const permissionContext = route.data['permissionContext'] as
    | OwnerType
    | undefined;

  if (isNullOrUndefined(expectedPermissions)) {
    return true; // No specific permissions required for this route
  }

  if (permissionService.canAccess(expectedPermissions, permissionContext)) {
    return true;
  } else {
    // Redirect to unauthorized page with details
    const permissionStr =
      typeof expectedPermissions === 'string'
        ? expectedPermissions
        : JSON.stringify(expectedPermissions);

    router
      .navigate(['/unauthorized'], {
        queryParams: { requiredPermission: permissionStr },
      })
      .catch(() => {});
    return false;
  }
};
