import { TranslateService } from '@ngx-translate/core';

import {
  createDropdownField,
  FormFieldConfig,
} from '../models/form-field.model';
import { INHERIT_OPTION_VALUE } from '../models/inherit-option.model';
import {
  ODOMETER_SOURCES,
  odometerSourceLabelKey,
} from '../models/odometer-source.model';
import { isNullOrUndefined } from './type-guards';

/**
 * Shared rendering for the odometer / distance source setting.
 *
 * The setting appears on the Settings card at all three account tiers, which are separate
 * components on different base classes, so this is a set of plain functions rather than a base
 * class. The rules it encodes:
 *
 * - A tier with no value set inherits from its parent. The read-only row shows what that
 *   currently resolves to, marked as inherited, rather than an unhelpful "None".
 * - The dropdown offers "Inherit from parent" everywhere except the top tier (distributor),
 *   which has nothing above it to inherit from.
 * - The Inherit entry is labelled with the value it currently resolves to, so choosing it is
 *   not a blind decision.
 */

/** Field key, matching the API property on client / vendor / distributor. */
export const ODOMETER_SOURCE_FIELD = 'odometerSource';

/** Human-readable label for a source value, falling back to the raw value if untranslated. */
export function formatOdometerSource(
  translate: TranslateService,
  source: string | null | undefined,
): string | null {
  if (isNullOrUndefined(source) || source === '') return null;

  const key = odometerSourceLabelKey(source);
  const translated = translate.instant(key);
  // ngx-translate echoes the key back when there is no entry for it
  return translated === key ? source : translated;
}

/**
 * The read-only row for the Settings grid.
 *
 * @param configured what this entity has stored (null/undefined means nothing set here)
 * @param effective what the API resolves this entity to
 * @param allowsInherit false at the top of the hierarchy, where an unset value is not
 *   inherited from anywhere - it simply falls through to the pipeline default
 * @param parentName the parent this entity inherits from, when known, so the row can name it
 */
export function buildOdometerSourceRow(
  translate: TranslateService,
  configured: string | null | undefined,
  effective: string | null | undefined,
  allowsInherit: boolean,
  parentName?: string | null,
): { key: string; value: string } {
  const label = translate.instant('ADMIN.ODOMETER_SOURCE.LABEL');

  const configuredLabel = formatOdometerSource(translate, configured);
  if (!isNullOrUndefined(configuredLabel)) {
    return { key: label, value: configuredLabel };
  }

  const effectiveLabel = formatOdometerSource(translate, effective);
  if (isNullOrUndefined(effectiveLabel)) {
    return { key: label, value: translate.instant('SHARED.COMMON.NONE') };
  }

  // Nothing above a distributor to inherit from: an unset value there is the pipeline
  // default, and calling it "inherited" would be simply untrue.
  if (!allowsInherit) {
    return {
      key: label,
      value: `${effectiveLabel} (${translate.instant('ADMIN.ODOMETER_SOURCE.DEFAULT')})`,
    };
  }

  // Inherited: show the resolved value and say where it came from
  const suffix = isNullOrUndefined(parentName)
    ? translate.instant('ADMIN.ODOMETER_SOURCE.INHERITED')
    : translate.instant('ADMIN.ODOMETER_SOURCE.INHERITED_FROM', {
        name: parentName,
      });

  return { key: label, value: `${effectiveLabel} (${suffix})` };
}

/**
 * The dropdown for the Settings form.
 *
 * @param inherited what this entity would use if it had no value of its own - NOT its
 *   effective value, which once a value is set here resolves to that same value and would
 *   make the Inherit option offer to inherit whatever is already selected
 * @param allowsInherit false only at the top of the hierarchy, where nothing sits above
 */
export function buildOdometerSourceField(
  translate: TranslateService,
  configured: string | null | undefined,
  inherited: string | null | undefined,
  allowsInherit: boolean,
): FormFieldConfig {
  const valueOptions = ODOMETER_SOURCES.map((source) => ({
    value: source,
    label: translate.instant(odometerSourceLabelKey(source)),
  }));

  const options = allowsInherit
    ? [buildInheritOption(translate, inherited), ...valueOptions]
    : valueOptions;

  return createDropdownField(
    ODOMETER_SOURCE_FIELD,
    translate.instant('ADMIN.ODOMETER_SOURCE.LABEL'),
    options,
    // An unset (inherited) value selects the Inherit entry rather than showing blank
    configured ?? (allowsInherit ? INHERIT_OPTION_VALUE : ''),
    { name: ODOMETER_SOURCE_FIELD, validations: [] },
  );
}

function buildInheritOption(
  translate: TranslateService,
  inherited: string | null | undefined,
): { value: string; label: string } {
  const inheritedLabel = formatOdometerSource(translate, inherited);

  return {
    value: INHERIT_OPTION_VALUE,
    label: isNullOrUndefined(inheritedLabel)
      ? translate.instant('ADMIN.ODOMETER_SOURCE.INHERIT')
      : translate.instant('ADMIN.ODOMETER_SOURCE.INHERIT_WITH_VALUE', {
          value: inheritedLabel,
        }),
  };
}

/**
 * Converts a submitted form value into what the API should store.
 *
 * The Inherit marker (and any blank) becomes a real null, so the API records "inherit" rather
 * than an unparsable empty enum - which would make the record fail to load on its next read.
 */
export function toOdometerSourceRequestValue(value: unknown): string | null {
  if (
    isNullOrUndefined(value) ||
    value === '' ||
    value === INHERIT_OPTION_VALUE
  ) {
    return null;
  }
  return String(value);
}
