import { AbstractControl, ValidationErrors, ValidatorFn } from '@angular/forms';
import { isNullOrUndefined } from './type-guards';

/**
 * Creates a phone number validator with configurable digit range
 * @param minDigits Minimum number of digits required
 * @param maxDigits Maximum number of digits allowed
 * @param errorKey Key to use in the validation error object
 * @param numberType Description of the number type for error messages
 */
function createPhoneValidator(
  minDigits: number,
  maxDigits: number,
  errorKey: string,
  numberType: string,
): ValidatorFn {
  return (control: AbstractControl): ValidationErrors | null => {
    if (isNullOrUndefined(control.value)) {
      return null;
    }

    const value = control.value.toString().trim();
    const digits = value.replaceAll(/\D/g, '');

    const validCharsRegex = /^[+]?[\d\s\-().]+$/;
    if (!validCharsRegex.test(value)) {
      return {
        [errorKey]: {
          value: control.value,
          message: `Invalid characters in ${numberType.toLowerCase()}`,
        },
      };
    }

    if (digits.length < minDigits || digits.length > maxDigits) {
      return {
        [errorKey]: {
          value: control.value,
          message: `${numberType} must contain ${minDigits}-${maxDigits} digits`,
        },
      };
    }

    return null;
  };
}

/**
 * Validates international phone numbers
 * Accepts various formats including:
 * - +1 123 456 7890
 * - +44 20 7123 4567
 * - (123) 456-7890
 * - 123-456-7890
 * - +61 2 1234 5678
 * Requires 7-15 digits (international standard)
 */
export function phoneValidator(): ValidatorFn {
  return createPhoneValidator(7, 15, 'phone', 'Phone number');
}

/**
 * Validates mobile phone numbers (typically 10-15 digits)
 * More lenient for international mobile formats
 */
export function mobileValidator(): ValidatorFn {
  return createPhoneValidator(10, 15, 'mobile', 'Mobile number');
}

/**
 * Validates that a SIM card number starts with '+' (international format).
 * Required for compatibility with LYNX synchronization.
 */
export function internationalSimNumberValidator(): ValidatorFn {
  return (control: AbstractControl): ValidationErrors | null => {
    if (isNullOrUndefined(control.value)) return null;
    const value = control.value.toString().trim();
    if (isNullOrUndefined(value)) return null;
    if (!(value as string).startsWith('+')) {
      return {
        internationalSimNumber: {
          value: control.value,
          message:
            "Please enter a valid international number starting with '+' (e.g., +27...)",
        },
      };
    }
    return null;
  };
}
